from typing import Dict, Any, List, Optional


class DiscountPolicy:
    """
    Handles calculation of promotional and customer-tier discounts.
    """

    PROMO_RATES = {
        "SUMMER10": 0.10,
        "SAVE20": 0.20,
    }

    TIER_RATES = {
        "gold": 0.05,
        "platinum": 0.10,
    }

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}

    def calculate_discount(
        self,
        subtotal: float,
        promo_code: Optional[str] = None,
        customer_tier: Optional[str] = None,
    ) -> float:
        discount = 0.0

        if promo_code in self.PROMO_RATES:
            discount += subtotal * self.PROMO_RATES[promo_code]
        elif promo_code == "FIXED15":
            discount += min(15.0, subtotal)

        if customer_tier in self.TIER_RATES:
            discount += (subtotal - discount) * self.TIER_RATES[customer_tier]

        return round(min(discount, subtotal), 2)


class ShippingCalculator:
    """
    Calculates shipping costs based on weight, method, customer tier, and order value.
    """

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}

    def calculate_shipping(
        self,
        weight_kg: float = 1.0,
        shipping_method: str = "standard",
        customer_tier: Optional[str] = None,
        discounted_subtotal: float = 0.0,
    ) -> float:
        if weight_kg <= 2.0:
            base_shipping = 5.0
        elif weight_kg <= 5.0:
            base_shipping = 10.0
        else:
            base_shipping = 15.0 + (weight_kg - 5.0) * 1.0

        if shipping_method == "express":
            shipping_cost = base_shipping + 8.0
        else:
            shipping_cost = base_shipping

        # VIP shipping rules: platinum tier or discounted_subtotal > 100 gets free standard shipping or $4 express discount
        if customer_tier == "platinum" or discounted_subtotal > 100.0:
            if shipping_method == "standard":
                shipping_cost = 0.0
            elif shipping_method == "express":
                shipping_cost = max(0.0, shipping_cost - 4.0)

        return round(shipping_cost, 2)


class TaxCalculator:
    """
    Calculates sales tax based on state rates applied to taxable amount (discounted subtotal + shipping).
    """

    DEFAULT_TAX_RATES = {
        "CA": 0.085,
        "NY": 0.080,
        "TX": 0.0625,
    }
    DEFAULT_FALLBACK_RATE = 0.05

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.tax_rates = self.config.get("tax_rates", self.DEFAULT_TAX_RATES)
        self.fallback_rate = self.config.get("fallback_tax_rate", self.DEFAULT_FALLBACK_RATE)

    def get_tax_rate(self, state: str) -> float:
        return self.tax_rates.get(state, self.fallback_rate)

    def calculate_tax(
        self,
        taxable_amount: float,
        state: str = "CA",
    ) -> float:
        rate = self.get_tax_rate(state)
        return round(taxable_amount * rate, 2)


def calculate_order(order_data: Dict[str, Any], config: Optional[Dict[str, Any]] = None) -> Dict[str, float]:
    """
    Calculates subtotal, discounts (promo code and tier), shipping (weight and tier/threshold),
    and tax (state-based on discounted subtotal + shipping).
    """
    if config is None:
        config = {}

    discount_policy = DiscountPolicy(config)
    shipping_calculator = ShippingCalculator(config)
    tax_calculator = TaxCalculator(config)

    items: List[Dict[str, Any]] = order_data.get("items", [])
    promo_code = order_data.get("promo_code")
    customer_tier = order_data.get("customer_tier")
    shipping_info = order_data.get("shipping", {})
    weight_kg = shipping_info.get("weight_kg", 1.0)
    shipping_method = shipping_info.get("method", "standard")
    state = order_data.get("state", "CA")

    # 1. Subtotal calculation
    subtotal = 0.0
    for item in items:
        subtotal += item.get("price", 0.0) * item.get("quantity", 1)
    subtotal = round(subtotal, 2)

    # 2. Discount calculation
    discount = discount_policy.calculate_discount(
        subtotal=subtotal,
        promo_code=promo_code,
        customer_tier=customer_tier,
    )
    discounted_subtotal = round(subtotal - discount, 2)

    # 3. Shipping calculation
    shipping_cost = shipping_calculator.calculate_shipping(
        weight_kg=weight_kg,
        shipping_method=shipping_method,
        customer_tier=customer_tier,
        discounted_subtotal=discounted_subtotal,
    )

    # 4. Tax calculation
    taxable_amount = discounted_subtotal + shipping_cost
    tax = tax_calculator.calculate_tax(
        taxable_amount=taxable_amount,
        state=state,
    )

    # 5. Total
    total = round(discounted_subtotal + shipping_cost + tax, 2)

    return {
        "subtotal": subtotal,
        "discount": discount,
        "discounted_subtotal": discounted_subtotal,
        "shipping": shipping_cost,
        "tax": tax,
        "total": total,
    }
